sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // Get the new reservation status value as a plain string
    var status = current.reservation_status.toString();

    // Get the sys_id of the workspace linked to this reservation
    var workspaceSysId = current.workspace.toString();

    // If no workspace is linked, stop the rule — nothing to update
    if (!workspaceSysId) return;

    // Query the Workspace Options table for the linked workspace record
    var ws = new GlideRecord('x_746154_workspa_0_workspace_options');

    // If the workspace record isn't found, stop the rule
    if (!ws.get(workspaceSysId)) return;

    // If someone is actively using the workspace (pending or checked in),
    // mark it as Unavailable so no one else can book it
    if (status == 'pending_check_in' || status == 'checked_in') {
        ws.status = 'unavailable';

    // If the reservation is over (checked out, no show, or cancelled),
    // mark the workspace as Available again for future bookings
    } else if (status == 'checked_out' || status == 'no_show' || status == 'cancelled') {
        ws.status = 'available';
    }

    // Save the updated status back to the Workspace Options record
    ws.update();

})(current, previous);
